# portage.map — logical name -> real Gentoo package atom(s).
# Only rows where the name actually differs (§1); bare names (zsh, git, curl,
# lsd, foot, fastfetch, unzip) resolve to unique atoms and pass through unchanged.
#
# Gentoo has no "build-essential" meta: the toolchain (gcc) is already in the
# @system set of every stage3, so `build` maps to gcc (present -> skipped, §2).

build = sys-devel/gcc
dev-headers = dev-libs/openssl
dmidecode = sys-apps/dmidecode
glib2 = dev-libs/glib

# chafa is native and current on Gentoo (media-gfx/chafa, ~current upstream), so
# the bare name still resolves and needs no method row. Build deps only, for the
# provide_chafa repair path in modules/yazi.sh.
chafa-build-deps = dev-libs/glib media-libs/freetype media-libs/libjpeg-turbo media-libs/libwebp media-libs/tiff dev-util/pkgconf
